// search-engine.js: full-text search over the book's text, run entirely in
// the browser. The corpus (4ed/search/corpus.json) is generated by
// tangleweave from the site's HTML (see tangleweave/search.go); it is
// downloaded the first time it's needed and indexed here.
//
// This file has no DOM dependencies so that it can also be run under node
// for testing; search.js provides the user interface.

(function (exports) {
'use strict';

///////////////////////////////////////////////////////////////////////////
// Tokenization

// Inline code is delimited by backticks in the corpus text and inline math
// by these private-use characters.
const MATH_OPEN = '\ue000', MATH_CLOSE = '\ue001';

const STOPWORDS = new Set(('a an and are as at be by for from has have in into is it its of on or ' +
                           'that the this to was were which with').split(' '));

// Lowercase and remove accents (so that "moller" matches "Möller").
function normalize(s) {
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

// Porter stemmer (M.F. Porter, "An algorithm for suffix stripping," 1980).
const stem = (function () {
    const step2list = {
        ational: 'ate', tional: 'tion', enci: 'ence', anci: 'ance', izer: 'ize', bli: 'ble',
        alli: 'al', entli: 'ent', eli: 'e', ousli: 'ous', ization: 'ize', ation: 'ate',
        ator: 'ate', alism: 'al', iveness: 'ive', fulness: 'ful', ousness: 'ous', aliti: 'al',
        iviti: 'ive', biliti: 'ble', logi: 'log'
    };
    const step3list = {
        icate: 'ic', ative: '', alize: 'al', iciti: 'ic', ical: 'ic', ful: '', ness: ''
    };
    const c = '[^aeiou]', v = '[aeiouy]', C = c + '[^aeiouy]*', V = v + '[aeiou]*';
    const mgr0 = new RegExp('^(' + C + ')?' + V + C);
    const meq1 = new RegExp('^(' + C + ')?' + V + C + '(' + V + ')?$');
    const mgr1 = new RegExp('^(' + C + ')?' + V + C + V + C);
    const sV = new RegExp('^(' + C + ')?' + v);
    const cache = new Map();

    function stemWord(w) {
        if (w.length < 3) return w;
        let re, re2, re3, re4, fp, stem;
        const firstch = w[0];
        if (firstch === 'y') w = 'Y' + w.substr(1);

        // Step 1a
        re = /^(.+?)(ss|i)es$/;
        re2 = /^(.+?)([^s])s$/;
        if (re.test(w)) w = w.replace(re, '$1$2');
        else if (re2.test(w)) w = w.replace(re2, '$1$2');

        // Step 1b
        re = /^(.+?)eed$/;
        re2 = /^(.+?)(ed|ing)$/;
        if (re.test(w)) {
            fp = re.exec(w);
            if (mgr0.test(fp[1])) w = w.replace(/.$/, '');
        } else if (re2.test(w)) {
            fp = re2.exec(w);
            stem = fp[1];
            if (sV.test(stem)) {
                w = stem;
                re2 = /(at|bl|iz)$/;
                re3 = new RegExp('([^aeiouylsz])\\1$');
                re4 = new RegExp('^' + C + v + '[^aeiouwxy]$');
                if (re2.test(w)) w = w + 'e';
                else if (re3.test(w)) w = w.replace(/.$/, '');
                else if (re4.test(w)) w = w + 'e';
            }
        }

        // Step 1c
        re = /^(.+?)y$/;
        if (re.test(w)) {
            fp = re.exec(w);
            stem = fp[1];
            if (sV.test(stem)) w = stem + 'i';
        }

        // Step 2
        re = /^(.+?)(ational|tional|enci|anci|izer|bli|alli|entli|eli|ousli|ization|ation|ator|alism|iveness|fulness|ousness|aliti|iviti|biliti|logi)$/;
        if (re.test(w)) {
            fp = re.exec(w);
            stem = fp[1];
            if (mgr0.test(stem)) w = stem + step2list[fp[2]];
        }

        // Step 3
        re = /^(.+?)(icate|ative|alize|iciti|ical|ful|ness)$/;
        if (re.test(w)) {
            fp = re.exec(w);
            stem = fp[1];
            if (mgr0.test(stem)) w = stem + step3list[fp[2]];
        }

        // Step 4
        re = /^(.+?)(al|ance|ence|er|ic|able|ible|ant|ement|ment|ent|ou|ism|ate|iti|ous|ive|ize)$/;
        re2 = /^(.+?)(s|t)(ion)$/;
        if (re.test(w)) {
            fp = re.exec(w);
            stem = fp[1];
            if (mgr1.test(stem)) w = stem;
        } else if (re2.test(w)) {
            fp = re2.exec(w);
            stem = fp[1] + fp[2];
            if (mgr1.test(stem)) w = stem;
        }

        // Step 5
        re = /^(.+?)e$/;
        if (re.test(w)) {
            fp = re.exec(w);
            stem = fp[1];
            re2 = new RegExp('^(' + C + ')?' + V + C + '(' + V + ')?$');
            re3 = new RegExp('^' + C + v + '[^aeiouwxy]$');
            if (mgr1.test(stem) || (meq1.test(stem) && !re3.test(stem))) w = stem;
        }
        re = /ll$/;
        if (re.test(w) && mgr1.test(w)) w = w.replace(/.$/, '');

        if (firstch === 'y') w = 'y' + w.substr(1);
        return w;
    }

    return function (w) {
        // Only stem plain words; leave identifiers like sigma_a and
        // Point3f alone.
        if (!/^[a-z]+$/.test(w)) return w;
        let s = cache.get(w);
        if (s === undefined) {
            s = stemWord(w);
            cache.set(w, s);
        }
        return s;
    };
})();

// Calls fn(word, start, end) for each token (normalized word) in the text;
// start and end are character offsets into the text. Inline math is
// skipped.
const tokenRegExp = /[\p{L}\p{N}_]+/gu;
function forEachToken(text, fn) {
    let mathStart = text.indexOf(MATH_OPEN);
    tokenRegExp.lastIndex = 0;
    let m;
    while ((m = tokenRegExp.exec(text)) !== null) {
        if (mathStart !== -1 && m.index > mathStart) {
            // Skip to the end of the math.
            const mathEnd = text.indexOf(MATH_CLOSE, mathStart);
            if (mathEnd === -1) break;
            if (m.index < mathEnd) {
                tokenRegExp.lastIndex = mathEnd + 1;
                mathStart = text.indexOf(MATH_OPEN, mathEnd);
                continue;
            }
            mathStart = text.indexOf(MATH_OPEN, mathEnd);
        }
        const word = /^[\x00-\x7f]*$/.test(m[0]) ? m[0].toLowerCase() : normalize(m[0]);
        // Possessives: "pbrt's" -> "pbrt".
        if (word === 's' && m.index > 0 && (text[m.index - 1] === '\u2019' || text[m.index - 1] === "'"))
            continue;
        fn(word, m.index, m.index + m[0].length);
    }
}

// Returns the tokens in the given text as an array of {word, stem, start,
// end}, or, if |positions| is false, an array of just their stems.
function tokenize(text, positions) {
    const result = [];
    if (positions)
        forEachToken(text, (word, start, end) => result.push({ word: word, stem: stem(word), start: start, end: end }));
    else
        forEachToken(text, word => result.push(stem(word)));
    return result;
}

///////////////////////////////////////////////////////////////////////////
// Query parsing

// A query is a list of terms; adjacent terms in quotes or joined by
// punctuation (e.g., Sphere::Intersect) also form phrases.
function parseQuery(q, prefixLast) {
    const terms = [], phrases = [];
    const re = /"([^"]*)"?|(\S+)/g;
    let m;
    while ((m = re.exec(q)) !== null) {
        const quoted = m[1] !== undefined;
        const toks = tokenize(quoted ? m[1] : m[2], true);
        if (toks.length === 0) continue;
        const first = terms.length;
        for (const t of toks)
            terms.push({ word: t.word, stem: t.stem, prefix: false, required: true });
        if (toks.length > 1) {
            // Words joined with :: or -> (e.g., Sphere::Intersect) are
            // matched exactly, without stemming.
            const exact = !quoted && /\w(::|->)\w/.test(m[2]);
            phrases.push({ start: first, end: terms.length, required: quoted, exact: exact });
        }
        if (quoted) {
            // Words in a quoted phrase are all required, stopwords
            // included.
            for (let i = first; i < terms.length; ++i) terms[i].quoted = true;
        }
    }

    // As the user is typing, the last word may be incomplete.
    if (prefixLast && terms.length > 0 && !/[\s"]$/.test(q))
        terms[terms.length - 1].prefix = true;

    // Stopwords don't need to be present unless they are in quotes or the
    // query is entirely stopwords.
    const allStop = terms.every(t => STOPWORDS.has(t.word));
    for (const t of terms)
        if (STOPWORDS.has(t.word) && !t.quoted && !allStop) t.required = false;

    return { text: q, terms: terms, phrases: phrases };
}

// Returns true if the text includes all of the query's required terms.
function hasAllTerms(text, query) {
    const toks = tokenize(text, true);
    return query.terms.every(t => !t.required ||
        toks.some(tok => tok.stem === t.stem || (t.prefix && tok.word.startsWith(t.word))));
}

///////////////////////////////////////////////////////////////////////////
// The index

// Weights for the various kinds of blocks; see searchBlock in
// tangleweave/search.go.
const KIND_WEIGHTS = {
    '1': 3.0, '2': 3.0, '3': 2.5, '4': 2.0, // headings
    'p': 1.0,   // paragraph
    'n': 1.6,   // fragment name
    'c': 0.55,  // code
    'f': 1.1,   // figure caption
    'b': 0.5,   // bibliography entry
    'x': 0.8,   // exercise
    't': 0.8,   // table row
    'o': 0.9,   // footnote
};

const KIND_NAMES = {
    '1': 'Chapter', '2': 'Section', '3': 'Section', '4': 'Section', 'p': 'Text',
    'n': 'Fragment', 'c': 'Code', 'f': 'Figure', 'b': 'Reference', 'x': 'Exercise',
    't': 'Table', 'o': 'Footnote',
};

class SearchIndex {
    constructor(corpus) {
        this.pages = corpus.pages;          // [url, chapter title, section title]
        this.blocks = corpus.blocks;        // [page, kind, heading, anchor, text]
        this.identifiers = corpus.identifiers || []; // [name, page, anchor]
        this.bookIndex = corpus.bookindex || [];      // {p: path, t: [[block, printed]], s: see}

        // Term -> postings: a flat array of [block, term frequency, ...]
        this.postings = new Map();
        // Word (unstemmed) -> stem, for prefix matching.
        const words = new Map();
        this.blockLength = new Uint32Array(this.blocks.length);
        let totalLength = 0;

        const counts = new Map();
        for (let bi = 0; bi < this.blocks.length; ++bi) {
            counts.clear();
            let length = 0;
            forEachToken(this.blocks[bi][4], word => {
                let s = words.get(word);
                if (s === undefined) {
                    s = stem(word);
                    words.set(word, s);
                }
                counts.set(s, (counts.get(s) || 0) + 1);
                ++length;
            });
            for (const [s, n] of counts) {
                let p = this.postings.get(s);
                if (p === undefined) {
                    p = [];
                    this.postings.set(s, p);
                }
                p.push(bi, n);
            }
            this.blockLength[bi] = length;
            totalLength += length;
        }
        this.averageLength = totalLength / this.blocks.length;

        this.words = Array.from(words.keys()).sort();
        this.wordStem = words;

        this.prepareIdentifiers();
        this.prepareBookIndex();
    }

    // Returns the stems of the indexed words that start with the given
    // prefix, most frequent first.
    expandPrefix(prefix, limit) {
        let lo = 0, hi = this.words.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (this.words[mid] < prefix) lo = mid + 1;
            else hi = mid;
        }
        const stems = new Set();
        for (let i = lo; i < this.words.length && this.words[i].startsWith(prefix); ++i)
            stems.add(this.wordStem.get(this.words[i]));
        return Array.from(stems)
            .sort((a, b) => this.postings.get(b).length - this.postings.get(a).length)
            .slice(0, limit || 30);
    }

    // Returns a Map from block index to term frequency for the term; for
    // prefix terms, matches of all of the completions are merged.
    termBlocks(term) {
        const stems = term.prefix ? this.expandPrefix(term.word) : [];
        if (!stems.includes(term.stem)) stems.push(term.stem);
        const result = new Map();
        let df = 0;
        for (const s of stems) {
            const p = this.postings.get(s);
            if (!p) continue;
            for (let i = 0; i < p.length; i += 2)
                result.set(p[i], (result.get(p[i]) || 0) + p[i + 1]);
        }
        return { blocks: result, stems: new Set(stems) };
    }

    // Full-text search. Returns {results: [{block, score}], partial, missing,
    // stems}, where partial is true if not all of the terms could be
    // matched in the same block, missing gives terms that don't appear at
    // all, and stems is the set of stems that were matched.
    search(query, maxResults) {
        const terms = query.terms;
        if (terms.length === 0) return { results: [], partial: false, missing: [], stems: new Set() };
        const N = this.blocks.length;
        const k1 = 1.2, b = 0.75;

        const termInfo = terms.map(t => {
            const tb = this.termBlocks(t);
            const df = tb.blocks.size;
            return {
                term: t, blocks: tb.blocks, stems: tb.stems,
                idf: Math.log(1 + (N - df + 0.5) / (df + 0.5))
            };
        });
        const allStems = new Set();
        for (const ti of termInfo) for (const s of ti.stems) allStems.add(s);

        // Required terms that don't appear anywhere are reported and
        // otherwise ignored.
        const missing = termInfo.filter(ti => ti.term.required && ti.blocks.size === 0).map(ti => ti.term);

        // Candidates: blocks that have all of the required terms. Start
        // with the rarest one.
        const required = termInfo.filter(ti => ti.term.required && ti.blocks.size > 0);
        const ordered = required.slice().sort((a, b) => a.blocks.size - b.blocks.size);
        let candidates = [];
        if (ordered.length > 0) {
            for (const bi of ordered[0].blocks.keys())
                if (ordered.every(ti => ti.blocks.has(bi))) candidates.push(bi);
        }

        // If no block has all of them, fall back to blocks that have most of
        // them.
        let partial = false;
        if (candidates.length === 0 && required.length > 1) {
            partial = true;
            const have = new Map();
            for (const ti of required)
                for (const bi of ti.blocks.keys()) have.set(bi, (have.get(bi) || 0) + 1);
            let most = 0;
            for (const n of have.values()) most = Math.max(most, n);
            if (most > 0)
                for (const [bi, n] of have) if (n === most) candidates.push(bi);
        }

        // BM25 scores, weighted by the kind of block.
        let scored = candidates.map(bi => {
            let score = 0;
            const len = this.blockLength[bi];
            for (const ti of termInfo) {
                const tf = ti.blocks.get(bi);
                if (!tf) continue;
                score += ti.idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * len / this.averageLength));
            }
            return { block: bi, score: score * KIND_WEIGHTS[this.blocks[bi][1]] };
        });
        scored.sort((a, b) => b.score - a.score);

        // Phrase and proximity bonuses for the top candidates, which
        // requires their tokens' positions.
        const nRescore = Math.min(scored.length, 400);
        const top = scored.slice(0, nRescore);
        for (const r of top) {
            const toks = tokenize(this.blocks[r.block][4], true);
            const bonus = this.proximity(toks, termInfo, query.phrases);
            if (bonus === -1) r.score = -1; // missing a required phrase
            else r.score *= 1 + bonus;
        }
        scored = top.filter(r => r.score >= 0).concat(scored.slice(nRescore));
        scored.sort((a, b) => b.score - a.score);
        if (maxResults) scored = scored.slice(0, maxResults);

        return { results: scored, partial: partial, missing: missing, stems: allStems };
    }

    // Returns a score bonus for the terms appearing close together in the
    // token stream (which may be negative), or -1 if a required phrase
    // isn't present.
    proximity(toks, termInfo, phrases) {
        let bonus = 0;
        for (const ph of phrases) {
            let found = false;
            for (let i = 0; i + ph.end - ph.start <= toks.length && !found; ++i) {
                found = true;
                for (let j = ph.start; j < ph.end; ++j)
                    if (ph.exact ? toks[i + j - ph.start].word !== termInfo[j].term.word
                                 : !termInfo[j].stems.has(toks[i + j - ph.start].stem)) {
                        found = false;
                        break;
                    }
            }
            if (found) bonus += ph.required ? 0.5 : 2.0;
            else if (ph.required) return -1;
            // An identifier was given but this block only has words with
            // the same stems (e.g., "sphere intersection" for
            // Sphere::Intersect).
            else if (ph.exact) return -0.5;
        }

        // Smallest window containing all of the (distinct) terms.
        const n = termInfo.length;
        if (n > 1 && n <= 8) {
            const last = new Array(n).fill(-1);
            let best = Infinity;
            for (let i = 0; i < toks.length; ++i) {
                let any = false;
                for (let j = 0; j < n; ++j)
                    if (termInfo[j].stems.has(toks[i].stem)) {
                        last[j] = i;
                        any = true;
                    }
                if (any && last.every(p => p >= 0)) {
                    const w = i - Math.min.apply(null, last) + 1;
                    best = Math.min(best, w);
                }
            }
            if (best < Infinity) bonus += Math.max(0, 1.5 * (1 - (best - n) / 12));
        }
        return bonus;
    }

    ///////////////////////////////////////////////////////////////////////
    // Identifiers

    prepareIdentifiers() {
        this.identKeys = this.identifiers.map(id => {
            const full = id[0].replace(/\(\)$/, '').toLowerCase();
            const member = full.includes('::') ? full.substr(full.lastIndexOf('::') + 2) : full;
            return { full: full, member: member };
        });
    }

    // Returns identifiers that match the query, best first.
    searchIdentifiers(q, prefix) {
        q = q.trim().replace(/\(\)$/, '').toLowerCase();
        if (!/^[a-z_][a-z0-9_:]*$/.test(q) || q.length < 2) return [];
        const result = [];
        for (let i = 0; i < this.identifiers.length; ++i) {
            const k = this.identKeys[i];
            let score = 0;
            if (k.full === q) score = 4;
            else if (k.member === q) score = 3;
            else if (prefix && k.full.startsWith(q)) score = 2;
            else if (prefix && q.length >= 3 && k.member.startsWith(q)) score = 1;
            if (score > 0) result.push({ ident: i, score: score });
        }
        result.sort((a, b) => b.score - a.score ||
                    this.identKeys[a.ident].full.length - this.identKeys[b.ident].full.length ||
                    (this.identKeys[a.ident].full < this.identKeys[b.ident].full ? -1 : 1));
        return result;
    }

    ///////////////////////////////////////////////////////////////////////
    // The book's index

    prepareBookIndex() {
        // Group subentries with their main entry.
        this.bookIndexMain = [];
        let current = null;
        this.bookIndex.forEach((e, i) => {
            e.stems = e.p.map(level => tokenize(level.replace(/`/g, ''), false));
            // E.g., "Bidirectional reflectance distribution functions (BRDFs)"
            const acronym = /\(([^)]*)\)\s*$/.exec(e.p[0]);
            e.acronym = acronym ? tokenize(acronym[1], false) : [];
            if (e.p.length === 1) {
                current = { entry: i, subentries: [] };
                this.bookIndexMain.push(current);
            } else if (current) {
                current.subentries.push(i);
            }
        });
    }

    // Returns {main, sub}: main index entries that match the query (with
    // all of their subentries), and subentries of other entries that
    // match.
    searchBookIndex(query) {
        const terms = query.terms.filter(t => t.required);
        if (terms.length === 0) return { main: [], sub: [] };
        const matchStem = (t, s) => t.prefix ? (s.startsWith(t.stem) || s.startsWith(t.word)) : s === t.stem;
        const levelMatches = stems => terms.filter(t => stems.some(s => matchStem(t, s))).length;

        const main = [], sub = [];
        for (const m of this.bookIndexMain) {
            const e = this.bookIndex[m.entry];
            const s0 = e.stems[0];
            const n0 = levelMatches(s0);
            if (n0 === terms.length) {
                // All of the terms are in the main entry; prefer entries
                // that are just the query (or its acronym), then shorter
                // ones.
                const extra = s0.filter(s => !STOPWORDS.has(s)).length - terms.length;
                let score = 10 - Math.min(extra, 8);
                if (e.acronym.length === terms.length && levelMatches(e.acronym) === terms.length) score = 9.5;
                main.push({ main: m, score: score });
                continue;
            }
            for (const si of m.subentries) {
                const se = this.bookIndex[si];
                const all = s0.concat(se.stems[1], se.stems[2] || []);
                if (levelMatches(se.stems[se.stems.length - 1]) > 0 && levelMatches(all) === terms.length)
                    sub.push({ main: m, entry: si, score: n0 > 0 ? 2 : 1 });
            }
        }
        // Entries that the matches refer to with "see" go right after them.
        for (const m of main.slice()) {
            const see = this.bookIndex[m.main.entry].s;
            if (!see) continue;
            const target = this.bookIndexMain.find(mm => this.bookIndex[mm.entry].p[0] === see);
            if (!target) continue;
            const existing = main.find(mm => mm.main === target);
            if (existing) existing.score = Math.max(existing.score, m.score - 0.01);
            else main.push({ main: target, score: m.score - 0.01 });
        }
        main.sort((a, b) => b.score - a.score);
        sub.sort((a, b) => b.score - a.score);
        return { main: main, sub: sub };
    }

    ///////////////////////////////////////////////////////////////////////
    // Information about blocks for presenting results.

    // Returns the chain of headings (block indices) for the block,
    // outermost first.
    headings(bi) {
        const h = [];
        for (let i = this.blocks[bi][2]; i >= 0; i = this.blocks[i][2]) h.unshift(i);
        return h;
    }

    // The section number for the block, e.g., "6.2.2".
    sectionNumber(bi) {
        const block = this.blocks[bi];
        const page = this.pages[block[0]];
        const titles = [];
        if (/^[1-4]$/.test(block[1])) titles.push(block[4]);
        for (const h of this.headings(bi).reverse()) titles.push(this.blocks[h][4]);
        titles.push(page[2], page[1]);
        for (const t of titles) {
            const m = /^(\d+(?:\.\d+)*|[A-Z](?:\.\d+)+)\s/.exec(t || '');
            if (m) return m[1];
        }
        // Appendix titles, e.g., "B Utilities"
        const m = /^([A-Z])\s/.exec(page[1]);
        return m ? m[1] : '';
    }
}

exports.SearchIndex = SearchIndex;
exports.parseQuery = parseQuery;
exports.hasAllTerms = hasAllTerms;
exports.tokenize = tokenize;
exports.stem = stem;
exports.normalize = normalize;
exports.STOPWORDS = STOPWORDS;
exports.KIND_NAMES = KIND_NAMES;
exports.MATH_OPEN = MATH_OPEN;
exports.MATH_CLOSE = MATH_CLOSE;

})(typeof module !== 'undefined' ? module.exports : (window.PBRSearchEngine = {}));
